class Solution:
    def generateMatrix(self, n: int) -> List[List[int]]:
        m = [[0] * n for _ in range(n)]
        top, bottom, left, right, num = 0, n - 1, 0, n - 1, 1
        while top <= bottom and left <= right:
            for c in range(left, right + 1):
                m[top][c] = num
                num += 1
            top += 1
            for r in range(top, bottom + 1):
                m[r][right] = num
                num += 1
            right -= 1
            if top <= bottom:
                for c in range(right, left - 1, -1):
                    m[bottom][c] = num
                    num += 1
                bottom -= 1
            if left <= right:
                for r in range(bottom, top - 1, -1):
                    m[r][left] = num
                    num += 1
                left += 1
        return m

impl Solution {
  pub fn generate_matrix(n: i32) -> Vec<Vec<i32>> {
    let n = n as usize;
    let mut m = vec![vec![0; n]; n];
    let (mut top, mut bottom, mut left, mut right, mut num) = (0i32, n as i32 - 1, 0i32, n as i32 - 1, 1);
    while top <= bottom && left <= right {
      for c in left..=right {
        m[top as usize][c as usize] = num;
        num += 1;
      }
      top += 1;
      for r in top..=bottom {
        m[r as usize][right as usize] = num;
        num += 1;
      }
      right -= 1;
      if top <= bottom {
        for c in (left..=right).rev() {
          m[bottom as usize][c as usize] = num;
          num += 1;
        }
        bottom -= 1;
      }
      if left <= right {
        for r in (top..=bottom).rev() {
          m[r as usize][left as usize] = num;
          num += 1;
        }
        left += 1;
      }
    }
    m
  }
}

